function StabilityDemo() {
  const [invalid, setInvalid] = useState(false);
  return (
    <FormStack>
      <Field
        label="Device name"
        hint="Shown in lists and the breadcrumb."
        error={invalid ? "Use letters, numbers and hyphens only" : undefined}
      >
        <Input defaultValue="ORB 7C71" width="medium" />
      </Field>
      <Field label="Asset tag" optional>
        <Input placeholder="DEMO-000000" width="medium" />
      </Field>
      <Button
        size="sm"
        variant="ghost"
        className="self-start"
        onClick={() => setInvalid((value) => !value)}
      >
        {invalid ? "Clear the error" : "Show an error"}
      </Button>
    </FormStack>
  );
}

